cd /workspace/tmp/tests && python3 - <<'EOF'
import sys
sys.path[:0]=['/workspace/project','/opt/emicro-deps']
from syntax import parse
tests=[
 '(' * 15 + 'match(A) and match(B)' + ')' * 15 + ' allow;',
 '(' * 14 + 'match(A) and match(B)' + ')' * 14 + ' allow;',
 'not(' * 15 + 'match(A)' + ')' * 15 + ' allow;',
 '(match(A) or match(B)) or match(C)',
]
for t in tests:
    try:
        r=parse(t+' allow;' if not t.endswith(';') else t)
        print('OK  ', repr(t[:60]), 'atoms',r.atoms)
    except Exception as e:
        print('REJ ', repr(t[:60]), type(e).__name__, e)
# balanced 32-atom tree
def bal(n):
    if n==1: return 'match(A)'
    a=n//2
    return '(%s or %s)'%(bal(a), bal(n-a))
p=bal(32)
print('depth-ish len', len(p))
try:
    r=parse(p+' allow;'); print('OK 32 atoms', r.atoms)
except Exception as e: print('REJ 32', e)
p=bal(33)
try:
    r=parse(p+' allow;'); print('OK 33 atoms', r.atoms)
except Exception as e: print('REJ 33', e)
EOF
